  await pgDb.query(`INSERT INTO "exam_pattern_section_difficulties" ("id", "sectionId", "difficultyLevel", "distributionType", "value", "isAutomatic", "createdAt") VALUES ('diff_chem_2', $1, 'MEDIUM', 'PERCENT', 40.0, false, CURRENT_TIMESTAMP)`, [sec2Id]);
  await pgDb.query(`INSERT INTO "exam_pattern_section_difficulties" ("id", "sectionId", "difficultyLevel", "distributionType", "value", "isAutomatic", "createdAt") VALUES ('diff_chem_3', $1, 'HARD', 'PERCENT', 30.0, false, CURRENT_TIMESTAMP)`, [sec2Id]);

  // Section 3: Mathematics
