  await pgDb.query(
    `INSERT INTO "exam_pattern_sections" (
      "id", "examPatternId", "subjectId", "name", "sequenceOrder", "numQuestions", "marksPerQuestion", "totalMarks", "marksCorrect", "marksWrong", "marksUnattempted", "createdAt", "updatedAt"
    ) VALUES ($1, $2, 'sub_math', 'Section C: Mathematics', 3, 10, 4.0, 40.0, 4.0, -1.0, 0.0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
    ON CONFLICT ("id") DO UPDATE SET "numQuestions" = 10, "totalMarks" = 40.0`,
    [sec3Id, patId]
  );
  await pgDb.query(`DELETE FROM "exam_pattern_section_topics" WHERE "sectionId" = $1`, [sec3Id]);
  await pgDb.query(`INSERT INTO "exam_pattern_section_topics" ("id", "sectionId", "topicId", "distributionType", "value", "createdAt") VALUES ('top_dist_math_1', $1, 'top_calculus', 'COUNT', 5, CURRENT_TIMESTAMP)`, [sec3Id]);
