  await pgDb.query(`INSERT INTO "exam_pattern_section_difficulties" ("id", "sectionId", "difficultyLevel", "distributionType", "value", "isAutomatic", "createdAt") VALUES ('diff_math_1', $1, 'EASY', 'PERCENT', 30.0, false, CURRENT_TIMESTAMP)`, [sec3Id]);
  await pgDb.query(`INSERT INTO "exam_pattern_section_difficulties" ("id", "sectionId", "difficultyLevel", "distributionType", "value", "isAutomatic", "createdAt") VALUES ('diff_math_2', $1, 'MEDIUM', 'PERCENT', 40.0, false, CURRENT_TIMESTAMP)`, [sec3Id]);
  await pgDb.query(`INSERT INTO "exam_pattern_section_difficulties" ("id", "sectionId", "difficultyLevel", "distributionType", "value", "isAutomatic", "createdAt") VALUES ('diff_math_3', $1, 'HARD', 'PERCENT', 30.0, false, CURRENT_TIMESTAMP)`, [sec3Id]);

  console.log('✅ Seeded clean JEE Main Exam Pattern blueprint ready for manual testing.');
